import{neuralTasks,validNeuralAnswer,reflexRoute,reflexLabels,advanceReflex,reactionTrials,meanNeural,corrective}from './neural-models.js?v=20261023-physicscomplete01';import{neuralTable}from './neural-figures.js?v=20261023-physicscomplete01';import{showNeural}from './neural-visuals.js?v=20261023-physicscomplete01';export{showNeural};
export function mountNeural(l,p,root,{save,feedback,done}){let tasks=neuralTasks[l.widget.slice(6)],w=p.widget;w.neuralTask??=0;w.neuralDrafts??={};w.neuralPassed??=[];let index=Math.min(tasks.length-1,w.neuralTask),t=tasks[index],v=w.neuralDrafts[index]??={state:0,answer:'',seen:[],step:0,runs:{quiet:0,distraction:0}};v.seen??=[];let $=s=>root.querySelector(s),remount=()=>mountNeural(l,p,root,{save,feedback,done});const field=(id,label,opts,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`,num=(id,label,val)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${val??''}">`,near=(x,a)=>x!==''&&x!==undefined&&Number.isFinite(Number(x))&&Math.abs(Number(x)-a)<.001;let body='',draw,record,valid;
if(t.type==='compare'){body=field('neuralState','Compare the condition',t.states.map((s,i)=>[i,s[1]]),v.state)+field('neuralPrediction',t.prompt,t.choices.map((s,i)=>[i,s]),v.answer)+'<button class="secondary" id="revealNeural">Reveal comparison →</button><p id="neuralReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.state;showNeural(t.scene,{kind:t.scene,state:t.states[v.state][0],step:t.scene==='synapse'?(r?5:0):undefined,title:t.title,concealed:!r,stateLabel:t.states[v.state][1],result:r?t.results[v.state]:''});$('#neuralReadout').textContent=r?t.results[v.state]:'Predict before revealing.';};record=()=>{if(v.revealed!==v.state||!validNeuralAnswer(t,v.state,v.answer))return false;if(!v.seen.includes(v.state))v.seen.push(v.state);return true;};valid=()=>v.seen.length===t.states.length;}
else if(t.type==='control'){v.value??=8;body='<p>Generic arbitrary-unit target5. Correct all three starting values.</p>'+field('controlValue','Starting value',[[8,'8 · above target'],[2,'2 · below target'],[5,'5 · at target']],v.value)+field('controlDirection','Corrective response',[['down','Reduce the value'],['up','Increase the value'],['hold','Maintain near target']],v.controlDirection);draw=()=>showNeural('control',{kind:'control',value:v.corrected?5:v.value,title:t.title,stateLabel:'Target5; '+(v.corrected?'corrected to5':'start '+v.value)});record=()=>{if(v.controlDirection!==corrective(Number(v.value)))return false;if(!v.seen.includes(v.value))v.seen.push(v.value);v.corrected=true;draw();return true;};valid=()=>v.seen.length===3;}
else if(t.type==='reflex'){body=field('reflexAction','Next stage',reflexRoute.map((s,i)=>[s,reflexLabels[i]]),v.reflexAction)+'<button class="secondary" id="advanceReflex">Advance route →</button><p id="neuralReadout"></p>'+field('neuralReason','Why is the immediate reflex rapid?',[['automatic','No conscious decision required first'],['conscious','It waits for conscious permission']],v.neuralReason);draw=()=>{showNeural('reflex',{kind:'reflex',step:Math.max(0,v.step-1),title:t.title,stateLabel:v.step+' /7 stages'});$('#neuralReadout').textContent='Recorded: '+reflexLabels.slice(0,v.step).join(' → ');};record=()=>v.step===7&&v.neuralReason==='automatic';valid=record;}
else if(t.type==='synapse'){body='<p>Advance the slowed chemical-synapse model from electrical arrival to the next impulse.</p><button class="secondary" id="advanceSignal">Advance signal stage →</button><p id="neuralReadout"></p>'+field('neuralReason','What crosses the chemical synaptic gap?',[['chemical','Chemical transmitter'],['wire','An uninterrupted electrical wire']],v.neuralReason);draw=()=>{showNeural('synapse',{kind:'synapse',step:v.step,title:t.title,stateLabel:'Stage '+v.step+' /5'});$('#neuralReadout').textContent=['Before arrival','Electrical impulse reaches the ending','Transmitter released','Transmitter diffuses across gap','Transmitter binds matching receptors','Next electrical impulse triggered'][v.step];};record=()=>v.step===5&&v.neuralReason==='chemical';valid=record;}
else if(t.type==='trials'){v.condition??='quiet';v.runs??={quiet:0,distraction:0};body='<p>Collect3 supplied simulated readings for each condition. This does not measure your own reaction time.</p>'+field('reactionCondition','Condition',[['quiet','Quiet'],['distraction','Distraction']],v.condition)+'<button class="secondary" id="collectReaction">Collect next supplied repeat →</button>'+num('reactionMean','Mean reaction time / ms',v.reactionMean)+field('neuralReason','Interpretation',[['lower','Lower time means faster response'],['higher','Higher time means faster response']],v.neuralReason);draw=()=>showNeural('data',{kind:'data',runs:v.runs,title:t.title,stateLabel:v.condition+' · '+v.runs[v.condition]+'/3 repeats'});record=()=>{if(v.runs[v.condition]!==3||!near(v.reactionMean,meanNeural(reactionTrials[v.condition]))||v.neuralReason!=='lower')return false;if(!v.seen.includes(v.condition))v.seen.push(v.condition);return true;};valid=()=>v.seen.length===2;}
else {body=neuralTable([['Quiet',170],['Distraction',210]],['Recorded condition','Mean time/ms'])+num('plotQuiet','Plot Quiet mean / ms',v.plotQuiet)+num('plotDistraction','Plot Distraction mean / ms',v.plotDistraction)+field('neuralAxes','Axes and scale',[['correct','x: condition; y: mean time/ms,0–250'],['wrong','x: participant age; y: unspecified']],v.neuralAxes)+field('neuralConclusion','Supported conclusion',[['limited','Distraction mean higher in this small supplied record'],['universal','Every person is always slower by exactly40ms']],v.neuralConclusion);draw=()=>showNeural('graph',{kind:'graph',points:[v.plotQuiet,v.plotDistraction],title:t.title,stateLabel:'Original supplied means; time in ms'});record=()=>near(v.plotQuiet,170)&&near(v.plotDistraction,210)&&v.neuralAxes==='correct'&&v.neuralConclusion==='limited';valid=record;}
root.innerHTML='<p class="activity-count">'+(index+1)+' / '+tasks.length+' · '+t.title+'</p>'+body+'<p id="neuralEvidence"></p><div class="lab-actions"><button class="secondary" id="recordNeural">Record reasoning</button><button class="secondary" id="nextNeural">Next challenge →</button></div><p id="neuralProgress">'+w.neuralPassed.length+' / '+tasks.length+' complete</p>';draw();const evidence=()=>$('#neuralEvidence').textContent=t.type==='compare'?t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · '):v.seen.length?'Recorded: '+v.seen.join(', '):'';evidence();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='neuralState'){v.state=Number(val||0);v.answer='';delete v.revealed;save();remount();return;}if(id==='controlValue'){v.value=Number(val||5);v.corrected=false;v.controlDirection='';save();remount();return;}if(id==='reactionCondition'){v.condition=val||'quiet';v.reactionMean='';save();remount();return;}if(id==='neuralPrediction')v.answer=val;else v[id]=val;save();if(t.type==='plot')draw();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id]=e.target.value;save();if(t.type==='plot')draw();};}
if($('#revealNeural'))$('#revealNeural').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validNeuralAnswer(t,v.state,v.answer)?'Prediction agrees. Record the evidence.':t.why,!validNeuralAnswer(t,v.state,v.answer));};
if($('#advanceReflex'))$('#advanceReflex').onclick=()=>{let n=advanceReflex(v.step,v.reflexAction);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.reflexAction='';save();remount();};
if($('#advanceSignal'))$('#advanceSignal').onclick=()=>{v.step=Math.min(5,v.step+1);save();draw();};
if($('#collectReaction'))$('#collectReaction').onclick=()=>{v.runs[v.condition]=Math.min(3,v.runs[v.condition]+1);save();draw();};
$('#recordNeural').onclick=()=>{if(!record()){feedback(t.why+' Check your evidence and reasoning.',true);return;}save();evidence();if(!valid()){feedback('Recorded. Complete the remaining conditions.');return;}if(!w.neuralPassed.includes(index))w.neuralPassed.push(index);if(w.neuralPassed.length===tasks.length){p.widgetDone=true;done();}save();$('#neuralProgress').textContent=w.neuralPassed.length+' / '+tasks.length+' complete';feedback('Evidence and reasoning recorded.');};$('#nextNeural').onclick=()=>{if(!w.neuralPassed.includes(index)){feedback('Complete this challenge first.',true);return;}w.neuralTask=(index+1)%tasks.length;save();remount();};}
